#[derive(Debug,Clone,Copy,PartialEq,Eq,Default)]pub struct Rect{pub x:i32,pub y:i32,pub w:i32,pub h:i32}impl Rect{pub const fn new(x:i32,y:i32,w:i32,h:i32)->Self{Self{x,y,w,h}}pub fn right(self)->i32{self.x+self.w}pub fn bottom(self)->i32{self.y+self.h}pub fn contains(self,x:i32,y:i32)->bool{x>=self.x&&x<self.right()&&y>=self.y&&y<self.bottom()}}
#[derive(Debug,Clone,Copy,PartialEq,Eq)]pub struct Layout{pub titlebar:Rect,pub tab_bar:Rect,pub toolbar:Rect,pub find_bar:Rect,pub status_bar:Rect,pub sidebar:Rect,pub editor:Rect,pub sidebar_open:bool,pub find_open:bool}
impl Layout{pub const TITLEBAR_HEIGHT:i32=32;pub const TAB_HEIGHT:i32=38;pub const TOOLBAR_HEIGHT:i32=36;pub const FIND_HEIGHT:i32=38;pub const STATUS_HEIGHT:i32=24;pub const SIDEBAR_WIDTH:i32=260;pub fn compute(width:u32,height:u32,sidebar_open:bool,find_open:bool)->Self{let(w,h)=(width.min(i32::MAX as u32)as i32,height.min(i32::MAX as u32)as i32);let titlebar=Rect::new(0,0,w,32);let tab_bar=Rect::new(0,32,w,38);let toolbar=Rect::new(0,70,w,36);let fh=if find_open{38}else{0};let find_bar=Rect::new(0,106,w,fh);let status_bar=Rect::new(0,h.saturating_sub(24),w,24);let top=find_bar.bottom();let sw=if sidebar_open{260.min(w)}else{0};let available=(status_bar.y-top).max(0);Self{titlebar,tab_bar,toolbar,find_bar,status_bar,sidebar:Rect::new(0,top,sw,available),editor:Rect::new(sw,top,(w-sw).max(0),available),sidebar_open,find_open}}pub fn titlebar_button_rects(self)->(Rect,Rect,Rect){let c=Rect::new(self.titlebar.right()-46,0,46,32);let m=Rect::new(c.x-46,0,46,32);let n=Rect::new(m.x-46,0,46,32);(n,m,c)}pub fn line_number_width(n:usize,char_width:i32)->i32{((n.max(1).to_string().len()as i32)+2)*char_width.max(1)}}
#[derive(Debug,Clone,Copy,PartialEq,Eq)]pub enum HitTarget{None,Drag,Minimize,Maximize,Close,Editor,Sidebar,Toolbar,FindBar,TabBar}
pub fn hit_test(l:Layout,x:i32,y:i32)->HitTarget{let(a,b,c)=l.titlebar_button_rects();if a.contains(x,y){HitTarget::Minimize}else if b.contains(x,y){HitTarget::Maximize}else if c.contains(x,y){HitTarget::Close}else if l.tab_bar.contains(x,y){HitTarget::TabBar}else if l.editor.contains(x,y){HitTarget::Editor}else if l.sidebar.contains(x,y){HitTarget::Sidebar}else if l.toolbar.contains(x,y){HitTarget::Toolbar}else if l.find_bar.contains(x,y){HitTarget::FindBar}else if l.titlebar.contains(x,y){HitTarget::Drag}else{HitTarget::None}}
